  public record LayerStats(
    String layer,
    int layerBytes,
    int layerFeatures,
    int layerGeometries,
    int layerAttrBytes,
    int layerAttrKeys,
    int layerAttrValues
  ) implements Comparable<LayerStats> {

    @Override
    public int compareTo(LayerStats o) {
      return layer.compareTo(o.layer);
    }
  }
